//! Original PhotoCraft palette data generated by Rust code.
//!
//! No palette files or copied third-party colour collections are embedded here.  The values are
//! generated from the documented level/ramp rules below and are covered by the catalog tests in
//! `palettes.rs`.

#[derive(Clone, Copy)]
pub(super) struct StaticBuiltin {
    pub(super) id: &'static str,
    pub(super) source: &'static str,
    pub(super) name: &'static str,
    pub(super) columns: u16,
    pub(super) colors: &'static [[u8; 3]],
    pub(super) color_names: &'static [&'static str],
}

const SOURCE: &str = "Original PhotoCraft Rust code; MIT OR Apache-2.0";

const BLACK_WHITE_COLORS: [[u8; 3]; 2] = [[0, 0, 0], [u8::MAX, u8::MAX, u8::MAX]];
const BLACK_WHITE_NAMES: [&str; 2] = ["Black", "White"];

// One entry for every encoded-sRGB 8-bit gray value, from black through white.
const fn grayscale_colors() -> [[u8; 3]; 256] {
    let mut colors = [[0, 0, 0]; 256];
    let mut index = 0;
    while index < colors.len() {
        let value = index as u8;
        colors[index] = [value, value, value];
        index += 1;
    }
    colors
}

const GRAYSCALE_COLORS: [[u8; 3]; 256] = grayscale_colors();
const GRAYSCALE_NAMES: [&str; 256] = [""; 256];

// The six levels are the evenly spaced encoded-sRGB values 0, 51, 102, 153, 204 and 255.
const fn rgb_cube_colors() -> [[u8; 3]; 216] {
    let mut colors = [[0, 0, 0]; 216];
    let mut index = 0;
    let mut red = 0;
    while red < 6 {
        let mut green = 0;
        while green < 6 {
            let mut blue = 0;
            while blue < 6 {
                colors[index] = [red as u8 * 51, green as u8 * 51, blue as u8 * 51];
                index += 1;
                blue += 1;
            }
            green += 1;
        }
        red += 1;
    }
    colors
}

const RGB_CUBE_COLORS: [[u8; 3]; 216] = rgb_cube_colors();
const RGB_CUBE_NAMES: [&str; 216] = [""; 216];

pub(super) static BUILTIN_DATA: &[StaticBuiltin] = &[
    StaticBuiltin {
        id: "photocraft-black-white",
        source: SOURCE,
        name: "PhotoCraft Black & White",
        columns: 2,
        colors: &BLACK_WHITE_COLORS,
        color_names: &BLACK_WHITE_NAMES,
    },
    StaticBuiltin {
        id: "photocraft-grayscale",
        source: SOURCE,
        name: "PhotoCraft Grayscale",
        columns: 16,
        colors: &GRAYSCALE_COLORS,
        color_names: &GRAYSCALE_NAMES,
    },
    StaticBuiltin {
        id: "photocraft-rgb-cube",
        source: SOURCE,
        name: "PhotoCraft RGB Cube",
        columns: 6,
        colors: &RGB_CUBE_COLORS,
        color_names: &RGB_CUBE_NAMES,
    },
];
